import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

record Msg {
    text: String
}

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Msg> = conc.channel(0)
    scope {
        let sender = task effect io {
            ch.send(Msg { text: "hello" })
            io.println("sent")
        }
        let receiver = task effect io {
            let v = ch.receive()
            match v {
                Some(m) => { io.println("got-hello") }
                None => { io.println("got-none") }
            }
        }
        let _ = sender.await()
        let _ = receiver.await()
    }
    return Ok(())
}
